/* 草稿：仅演示 HSE 启动检查，不是完整升频流程 */
RCC_HSEConfig(RCC_HSE_ON);
ErrorStatus ready = RCC_WaitForHSEStartUp();
if (ready == ERROR) {
    /* 保持安全时钟，向调用者报告失败 */
}

/* 草稿前提：HCLK 已正确配置为 72 MHz */
RCC_PCLK1Config(RCC_HCLK_Div2);  /* PCLK1 = 36 MHz */
RCC_PCLK2Config(RCC_HCLK_Div1);  /* PCLK2 = 72 MHz */
RCC_ClocksTypeDef clocks;
RCC_GetClocksFreq(&clocks);

/* 草稿前提：TIM2 内部时钟 72 MHz，边沿向上计数 */
TIM_TimeBaseInitTypeDef cfg;
TIM_TimeBaseStructInit(&cfg);
cfg.TIM_Prescaler = 7200 - 1;
cfg.TIM_Period = 10000 - 1;
cfg.TIM_CounterMode = TIM_CounterMode_Up;
TIM_TimeBaseInit(TIM2, &cfg);

/* 草稿：USART1 的 GPIO 与外设时钟分别开启 */
RCC_APB2PeriphClockCmd(
    RCC_APB2Periph_GPIOA | RCC_APB2Periph_USART1,
    ENABLE);

/* 草稿：PA0 开漏，外部已接合适上拉 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA, ENABLE);
GPIO_InitTypeDef cfg;
GPIO_StructInit(&cfg);
cfg.GPIO_Pin = GPIO_Pin_0;
cfg.GPIO_Mode = GPIO_Mode_Out_OD;
cfg.GPIO_Speed = GPIO_Speed_2MHz;
GPIO_Init(GPIOA, &cfg);
GPIO_SetBits(GPIOA, GPIO_Pin_0); /* 释放，不主动驱动高 */

/* 草稿片段：cfg 已初始化，其他字段已配置 */
cfg.GPIO_Mode = GPIO_Mode_Out_PP;
cfg.GPIO_Speed = GPIO_Speed_2MHz;
GPIO_Init(GPIOA, &cfg);

/* 草稿：PA0，按键闭合到 GND */
GPIO_InitTypeDef cfg;
GPIO_StructInit(&cfg);
cfg.GPIO_Pin = GPIO_Pin_0;
cfg.GPIO_Mode = GPIO_Mode_IPU;
GPIO_Init(GPIOA, &cfg); /* 前提：GPIOA 时钟已开 */
uint8_t pressed = (GPIO_ReadInputDataBit(GPIOA, GPIO_Pin_0) == 0);

/* 草稿：PA0 已配置输出，时钟已开启 */
GPIO_SetBits(GPIOA, GPIO_Pin_0);
uint8_t pinLevel = GPIO_ReadInputDataBit(GPIOA, GPIO_Pin_0);
uint8_t latch = GPIO_ReadOutputDataBit(GPIOA, GPIO_Pin_0);

/* 草稿：8 个数据位 + 偶校验 + 1 个停止位 */
USART_InitTypeDef cfg;
USART_StructInit(&cfg);
cfg.USART_BaudRate = 9600;
cfg.USART_WordLength = USART_WordLength_9b;
cfg.USART_Parity = USART_Parity_Even;
cfg.USART_StopBits = USART_StopBits_1;
cfg.USART_Mode = USART_Mode_Tx | USART_Mode_Rx;
USART_Init(USART1, &cfg); /* 时钟与 GPIO 需先配置 */

/* 草稿：默认 USART1 映射，前提：双方 3.3 V 逻辑兼容 */
RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_USART1, ENABLE);
GPIO_InitTypeDef cfg;
GPIO_StructInit(&cfg);
cfg.GPIO_Pin = GPIO_Pin_9;
cfg.GPIO_Mode = GPIO_Mode_AF_PP;
cfg.GPIO_Speed = GPIO_Speed_2MHz;
GPIO_Init(GPIOA, &cfg);
cfg.GPIO_Pin = GPIO_Pin_10;
cfg.GPIO_Mode = GPIO_Mode_IN_FLOATING;
GPIO_Init(GPIOA, &cfg);

/* 草稿：完整时钟、GPIO 与 cfg 其他字段已配置 */
RCC_ClocksTypeDef clocks;
RCC_GetClocksFreq(&clocks);
cfg.USART_BaudRate = 9600;
USART_Init(USART1, &cfg);

/* 草稿片段：USART1 已配置并使能；有循环上限 */
uint32_t budget = 100000;
while (USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET) {
    if (--budget == 0) { return; } /* 向上层报告超时更合适 */
}
USART_SendData(USART1, 0x55);

/* 草稿：只展示硬件 START 请求；需状态机及超时 */
I2C_GenerateSTART(I2C1, ENABLE);
/* 等待实际 START 条件及地址阶段，不能紧接着无条件发送 */

/* 草稿：仅演示线路操作，非完整软件 I²C 驱动 */
void SoftI2C_SDARelease(void) {
    GPIO_SetBits(GPIOB, GPIO_Pin_7);
}
uint8_t SoftI2C_ReadSDA(void) {
    return GPIO_ReadInputDataBit(GPIOB, GPIO_Pin_7);
}

/* 草稿：事务前需确认 BUSY、错误及初始化条件 */
I2C_GenerateSTART(I2C1, ENABLE);
uint32_t budget = 100000;
while (I2C_CheckEvent(I2C1, I2C_EVENT_MASTER_MODE_SELECT) == ERROR) {
    if (--budget == 0) { return; }
    /* 此处还需检查错误状态，并向上层报告 */
}

